# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ESMÂ-İ HÜSNÂ VE İLETİŞİMDE BAĞLAMINA UYGUN KULLANIM (DKAB.10.2.2)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">RAHMET, RIZIK VE ŞİFA İSİMLERİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Er-Rahmân ve Er-Rahîm : Sonsuz şefkat ve merhamet</text>\n  <text x="35" y="112" font-size="11.2" fill="#1e3a8a">• Er-Rezzâk : Maddi ve manevi rızık veren</text>\n  <text x="35" y="136" font-size="11.2" fill="#1e3a8a">• Eş-Şâfî : Hastalara şifa ve afiyet bahşeden</text>\n  <text x="35" y="160" font-size="11.2" fill="#1e3a8a">• El-Gaffâr ve Et-Tevvâb : Günahları bağışlayan, tövbeleri kabul eden</text>\n  <text x="35" y="184" font-size="11.2" fill="#1e3a8a">• El-Vedûd : Kullarını çok seven ve sevilmeye layık olan</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">İLİM, ADALET VE KORUMA İSİMLERİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• El-Alîm ve El-Habîr : Her şeyi en ince ayrıntısıyla bilen</text>\n  <text x="370" y="112" font-size="11.2" fill="#14532d">• El-Hakîm : Her işi hikmetli ve yerli yerinde olan</text>\n  <text x="370" y="136" font-size="11.2" fill="#14532d">• El-Adl : Mutlak adalet sahibi, zulmetmeyen</text>\n  <text x="370" y="160" font-size="11.2" fill="#14532d">• El-Hafîz ve El-Vekîl : Koruyup gözeten, tevekkül edilen</text>\n  <text x="370" y="184" font-size="11.2" fill="#14532d">• Es-Selâm : Esenlik kaynağı, kullarını selamete çıkaran</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«En güzel isimler (Esmâ-i Hüsnâ) Allah\'ındır; öyleyse O\'na o güzel isimlerle dua edin.» (A\'râf, 7/180)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İSLAM\'DA AİLE KURUMU VE TEMEL İLKELERİ (DKAB.10.3.1)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fdf4ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">RÛM SURESİ 21. AYET ÜÇ TEMEL KAVRAM</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">• Sekînet (Litaskünû): Gönül huzuru, güven ve sükûnet yuvası</text>\n  <text x="35" y="112" font-size="11.2" fill="#581c87">• Meveddet: Karşılıklı derin sevgi, muhabbet ve bağlılık</text>\n  <text x="35" y="136" font-size="11.2" fill="#581c87">• Rahmet: Şefkat, merhamet, fedakârlık ve koruyuculuk</text>\n  <text x="35" y="160" font-size="11.2" fill="#581c87">• Nikâh Akdi: Hukuki ve ahlaki sorumluluk yükleyen sözleşme</text>\n  <text x="35" y="184" font-size="11.2" fill="#581c87">• Neslin Korunması: Zarûriyyât-ı Hamse\'nin temel halkası</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">AİLE İÇİ HAK VE SORUMLULUKLAR</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">• Eşler arası istişare (şûra) ve ortak karar alma</text>\n  <text x="370" y="112" font-size="11.2" fill="#7c2d12">• Anne-babaya ihsan ve güzel söz (İsrâ, 17/23)</text>\n  <text x="370" y="136" font-size="11.2" fill="#7c2d12">• Çocuklara güzel isim koyma ve salih terbiye verme</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Sıla-i rahim: Akrabalık bağlarını koruma ve ziyaret</text>\n  <text x="370" y="184" font-size="11.2" fill="#7c2d12">• Mahremiyet ve aile sırlarının korunması</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«Sizin en hayırlınız, ailesine karşı en hayırlı ve merhametli olanınızdır.» (Tirmizî, Menâkıb, 63)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İSLAM\'DA SOSYAL DAYANIŞMA VE BİRLİKTE YAŞAMA AHLAKI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">SOSYAL DAYANIŞMA KURUMLARI</text>\n  <text x="35" y="88" font-size="11.2" fill="#064e3b">• İnfak, Zekât ve Sadaka: Servetin adil paylaşımı</text>\n  <text x="35" y="112" font-size="11.2" fill="#064e3b">• Sadaka-i Câriye ve Vakıf Kültürü: Kalıcı hayır kurumları</text>\n  <text x="35" y="136" font-size="11.2" fill="#064e3b">• Karz-ı Hasen: Karşılık beklemeden verilen güzel ödünç</text>\n  <text x="35" y="160" font-size="11.2" fill="#064e3b">• Îsâr Ahlakı: Kendisi muhtaçken kardeşini tercih etme</text>\n  <text x="35" y="184" font-size="11.2" fill="#064e3b">• Komşuluk Hakkı: «Komşusu açken tok yatan bizden değildir»</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">BİRLİKTE YAŞAMA VE TOPLUMSAL BARIŞ</text>\n  <text x="370" y="88" font-size="11.2" fill="#713f12">• Uhuvvet (Kardeşlik): Müminler ancak kardeştir (Hucurât, 10)</text>\n  <text x="370" y="112" font-size="11.2" fill="#713f12">• Adalet ve Emanet: İşi ehline verme, hakkaniyetle hükmetme</text>\n  <text x="370" y="136" font-size="11.2" fill="#713f12">• İyilik ve Takvada Yardımlaşma (Mâide, 5/2)</text>\n  <text x="370" y="160" font-size="11.2" fill="#713f12">• Gıybet, İftira, Tecessüs ve Suizandan Kaçınma</text>\n  <text x="370" y="184" font-size="11.2" fill="#713f12">• Sulh ve Islah: Kırgınlıkları giderip barışı tesis etme</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Müslümanlar bir binanın birbirini kenetleyip destekleyen tuğlaları veya tek bir vücudun organları gibidir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
